    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v], default=bg)

    # Special demonstrated pattern.
    active_rows = [r for r in range(h) if fg in grid[r]]
