        return out

    # Group consecutive rows containing the foreground color.
    groups = []
    for r in active_rows:
        if not groups or r != groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)

    if len(groups) < 2:
        return out

    # Use the densest repeated group as the reference and mark missing
    # foreground cells in the other aligned groups.
    source = max(groups, key=lambda g: sum(grid[r][c] == fg for r in g for c in range(w)))
    for target in groups:
